```js
var express = require('express');
var app = express();
var server = require('http').createServer(app);
var io = require('socket.io')(server);

app.use(express.static(__dirname + '/public'));
app.get('/', function(req, res) {
  res.sendFile(__dirname + '/public/index.html');
});

// 权威玩家状态
var players = {}; // { socketId: { id, x, y, vx, vy, frame, ... } }

// on connect
io.on('connection', function(socket) {
  console.log('connect', socket.id);

  socket.on('join', function(meta) {
    players[socket.id] = Object.assign({
      id: socket.id,
      x: meta && meta.x || 0,
      y: meta && meta.y || 0,
      vx: 0, vy: 0, frame: 0, state: 'idle'
    }, meta || {});
    socket.emit('joined', { id: socket.id });
    socket.broadcast.emit('playerJoined', players[socket.id]);
    console.log('player joined', socket.id);
  });

  // 客户端发送输入（方向/动作等）
  socket.on('input', function(inp) {
    // 简单：直接将输入写入玩家对象（更复杂的逻辑放在服务器侧模拟）
    var p = players[socket.id];
    if (!p) return;
    p.lastInput = inp;
    // 可选：即时更新位置（简单权威移动示例）
    if (inp && inp.dir) {
      if (inp.dir === 'left') p.x -= 5;
      else if (inp.dir === 'right') p.x += 5;
      else if (inp.dir === 'up') p.y -= 5;
      else if (inp.dir === 'down') p.y += 5;
    }
    if (typeof inp.frame !== 'undefined') p.frame = inp.frame;
    // 其他字段按需处理
  });

  socket.on('disconnect', function() {
    console.log('disconnect', socket.id);
    if (players[socket.id]) {
      socket.broadcast.emit('playerLeft', { id: socket.id });
      delete players[socket.id];
    }
  });
});

// 周期广播权威状态（20Hz）
setInterval(function() {
  // 只发送必要字段，避免过大 payload
  var snapshot = {};
  Object.keys(players).forEach(function(k) {
    var p = players[k];
    snapshot[k] = { id: p.id, x: p.x, y: p.y, frame: p.frame, state: p.state };
  });
  io.emit('state', snapshot);
}, 50);

server.listen(3000, function(){
  console.log('listening on *:3000');
});
```

2) 新增客户端模块 src/network.js
```js
"use strict";
// 客户端网络层：建立 socket.io 连接，发送 input，广播服务器快照为 DOM 事件
var ioClient = window.io; // public/socket.io.js 已载入
var socket = null;

function connect() {
  if (socket) return socket;
  socket = io();

  socket.on('connect', function() {
    console.log('network connected', socket.id);
    socket.emit('join', { x: 0, y: 0 }); // 初始元数据，可改为当前玩家坐标
  });

  socket.on('joined', function(data){
    console.log('joined ok', data);
  });

  socket.on('playerJoined', function(p){
    window.dispatchEvent(new CustomEvent('network-player-joined', { detail: p }));
  });

  socket.on('playerLeft', function(p){
    window.dispatchEvent(new CustomEvent('network-player-left', { detail: p }));
  });

  socket.on('state', function(snapshot){
    // dispatch 一个全局事件，游戏主循环或系统模块可监听并合并远端实体
    window.dispatchEvent(new CustomEvent('network-state', { detail: snapshot }));
  });

  return socket;
}

function sendInput(inp) {
  if (!socket) connect();
  socket.emit('input', inp);
}

window.Network = {
  connect: connect,
  sendInput: sendInput,
  _socket: socket
};
```

