## 2) 客户端：创建一个最小网络模块

新建 [src/network.js](src/network.js)：

```js
"use strict";

var socket = null;

function connect() {
  if (socket) return socket;
  if (!window.io) {
    console.warn("socket.io not ready yet");
    return null;
  }

  socket = window.io();

  socket.on('connect', function() {
    console.log('network connected', socket.id);
    socket.emit('join', {
      x: 0,
      y: 0,
      pose: 'idle',
      frame: 0
    });
  });

  socket.on('joined', function(data) {
    console.log('joined ok', data);
  });

  socket.on('playerJoined', function(player) {
    window.dispatchEvent(new CustomEvent('network-player-joined', {
      detail: player
    }));
  });

  socket.on('playerLeft', function(player) {
    window.dispatchEvent(new CustomEvent('network-player-left', {
      detail: player
    }));
  });

  socket.on('state-update', function(state) {
    window.dispatchEvent(new CustomEvent('network-state-update', {
      detail: state
    }));
  });

  return socket;
}

function sendState(state) {
  if (!socket) connect();
  if (!socket) return;
  socket.emit('state', state);
}

window.Network = {
  connect: connect,
  sendState: sendState
};

module.exports = {
  connect: connect,
  sendState: sendState
};
```

---

## 3) 让入口文件初始化网络

把 [src/entry.js](src/entry.js) 改成：

```js
